SELECT s.id,true,true,true,ARRAY['End-of-tenancy compliance','Security-deposit preparation','Immediate rental/listing preparation'],ARRAY['ONE_TIME','PACKAGE_COMPONENT','CUSTOM_PROJECT'],'Single-event transition milestone','Can combine with move/transition, disposal and other property services.','Time-critical; photo/evidence trail and zero-tolerance QA required.','Direct purchase permitted; may be packaged.','LOCKED','Gate 01 review based on current commercial behavior matrix. No promise of deposit refund.' FROM public.services s WHERE s.sku='DNI-01A-003'
ON CONFLICT(service_id) DO UPDATE SET independent_purchase=EXCLUDED.independent_purchase,multi_division_composable=EXCLUDED.multi_division_composable,multi_service_work_order=EXCLUDED.multi_service_work_order,primary_use_cases=EXCLUDED.primary_use_cases,primary_form_factors=EXCLUDED.primary_form_factors,customer_journey=EXCLUDED.customer_journey,composition_notes=EXCLUDED.composition_notes,fulfillment_implications=EXCLUDED.fulfillment_implications,ingress_rule=EXCLUDED.ingress_rule,gate_status=EXCLUDED.gate_status,reviewed_at=now(),notes=EXCLUDED.notes;

