SELECT s.id,false,true,true,ARRAY['Weekly textile management','Convenience','Garment/textile preservation'],ARRAY['MEMBERSHIP_ALLOCATION','PROGRAM_COMPONENT','ADD_ON'],'High-frequency routine lifestyle loop','May combine with cleaning, linen and household programs.','Requires textile-processing workflow, transport/bag tracking, facility/vendor coordination and chain-of-custody controls.','Must be attached to an eligible cleaning service or membership/program; standalone purchase disabled by current commercial rule.','LOCKED','Gate 01 review based on current commercial behavior matrix.' FROM public.services s WHERE s.sku='DNI-01A-004'
